def solve(messages):
    from abc import ABC, abstractmethod

    class Channel(ABC):
        @abstractmethod
        def send(self, text):
            raise NotImplementedError

    class Email(Channel):
        def send(self, text):
            return "email:" + text

    def broadcast(channel, items):
        return [channel.send(item) for item in items]

    return broadcast(Email(), messages)
